    """Move every colored object vertically so its top aligns with the highest object."""
    h, w = len(grid), len(grid[0])
    rows = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                rows.setdefault(color, []).append((r, c))
    if not rows:
        return [row[:] for row in grid]
    target_top = min(r for cells in rows.values() for r, _ in cells)
    out = [[0] * w for _ in range(h)]
    for color, cells in rows.items():
        top = min(r for r, _ in cells)
        shift = target_top - top
        for r, c in cells:
            out[r + shift][c] = color
    return out
